-- Freightwizard baseline schema: every table as it exists in production
-- (generated by supabase/tools/baseline-from-openapi.mjs from production's
-- table definitions on 2026-10-14; no data). Run first on a new project,
-- then the dated migrations in order, then supabase/seed.sql for development.
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;

-- Enum types
DO $$ BEGIN CREATE TYPE public."email_provider" AS ENUM ('gmail', 'outlook'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public."email_status" AS ENUM ('pending', 'reviewed', 'actioned', 'snoozed', 'archived'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public."email_priority" AS ENUM ('high', 'medium', 'low'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public."email_intent" AS ENUM ('booking_request', 'booking_confirmation', 'arrival_notice', 'departure_notice', 'invoice', 'delay_notification', 'document_request', 'rate_inquiry', 'tracking_update', 'general_inquiry', 'other'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- Tables
CREATE TABLE IF NOT EXISTS public."email_accounts" (
  "id" uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
  "user_id" uuid,
  "organization_id" uuid,
  "provider" email_provider NOT NULL,
  "email_address" text NOT NULL,
  "access_token" text NOT NULL,
  "refresh_token" text NOT NULL,
  "token_expires_at" timestamp with time zone NOT NULL,
  "last_sync_at" timestamp with time zone,
  "sync_cursor" text,
  "is_active" boolean DEFAULT true,
  "webhook_expiry" timestamp with time zone,
  "webhook_resource_id" text,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS public."email_activity" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "user_id" uuid,
  "email_id" text NOT NULL,
  "action" text NOT NULL,
  "intent" text,
  "priority" text,
  "response_time_minutes" integer,
  "created_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS public."email_analysis" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "email_id" text NOT NULL,
  "user_id" uuid,
  "gmail_session_id" text,
  "thread_id" text,
  "subject" text,
  "from_email" text,
  "intent" text,
  "priority" text,
  "mode" text,
  "pol" text,
  "pod" text,
  "incoterm" text,
  "cargo_type" text,
  "container_type" text,
  "container_count" integer,
  "weight_kg" numeric,
  "booking_number" text,
  "container_number" text,
  "vessel_name" text,
  "eta" timestamp with time zone,
  "missing_info" jsonb,
  "summary" text,
  "suggested_reply" text,
  "confidence_score" numeric,
  "replied_at" timestamp with time zone,
  "response_time_minutes" integer,
  "created_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id"),
  UNIQUE ("email_id", "user_id")
);
CREATE TABLE IF NOT EXISTS public."country_integrations" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "session_id" text,
  "country_code" text,
  "integration_key" text,
  "api_key" text,
  "api_secret" text,
  "extra_fields" jsonb,
  "is_active" boolean DEFAULT true,
  "last_verified_at" timestamp with time zone,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id"),
  UNIQUE ("session_id", "country_code", "integration_key")
);
CREATE TABLE IF NOT EXISTS public."activity_log" (
  "id" uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
  "organization_id" uuid,
  "user_id" uuid,
  "email_id" uuid,
  "action" text NOT NULL,
  "details" jsonb,
  "created_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS public."analysis_queue" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "email_id" text NOT NULL,
  "user_email" text NOT NULL,
  "subject" text,
  "from_email" text,
  "body" text,
  "thread_id" text,
  "status" text DEFAULT 'pending',
  "result" jsonb,
  "created_at" timestamp with time zone DEFAULT now(),
  "processed_at" timestamp with time zone,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS public."subscriptions" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "session_id" text,
  "user_email" text NOT NULL,
  "stripe_customer_id" text,
  "stripe_subscription_id" text,
  "plan" text DEFAULT 'trial',
  "status" text DEFAULT 'trialing',
  "trial_analyses_used" integer DEFAULT 0,
  "trial_started_at" timestamp with time zone DEFAULT now(),
  "current_period_start" timestamp with time zone,
  "current_period_end" timestamp with time zone,
  "cancel_at_period_end" boolean DEFAULT false,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id"),
  UNIQUE ("user_email")
);
CREATE TABLE IF NOT EXISTS public."user_preferences" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "user_id" uuid,
  "theme" text DEFAULT 'dark',
  "language" text DEFAULT 'en',
  "auto_analyze" boolean DEFAULT true,
  "email_notifications" boolean DEFAULT true,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id"),
  UNIQUE ("user_id")
);
CREATE TABLE IF NOT EXISTS public."gmail_sessions" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "session_id" text NOT NULL,
  "user_id" uuid,
  "gmail_email" text NOT NULL,
  "access_token" text,
  "refresh_token" text,
  "token_expiry" timestamp with time zone,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  "provider" text DEFAULT 'google',
  "user_name" text,
  "last_active" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id"),
  UNIQUE ("session_id")
);
CREATE TABLE IF NOT EXISTS public."profiles" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "auth_user_id" uuid,
  "email" text NOT NULL,
  "full_name" text,
  "avatar_url" text,
  "plan" text DEFAULT 'starter',
  "emails_this_month" integer DEFAULT 0,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  "role" text DEFAULT 'employee',
  "team_id" uuid,
  PRIMARY KEY ("id"),
  UNIQUE ("email")
);
CREATE TABLE IF NOT EXISTS public."email_replies" (
  "id" uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
  "email_id" uuid,
  "subject" text NOT NULL,
  "body_text" text NOT NULL,
  "body_html" text,
  "tone" text DEFAULT 'professional',
  "reply_type" text DEFAULT 'reply',
  "is_selected" boolean DEFAULT false,
  "is_sent" boolean DEFAULT false,
  "sent_at" timestamp with time zone,
  "sent_by" uuid,
  "edited_body" text,
  "created_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS public."analytics_daily" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "user_id" uuid,
  "date" date NOT NULL,
  "emails_received" integer DEFAULT 0,
  "emails_analyzed" integer DEFAULT 0,
  "emails_replied" integer DEFAULT 0,
  "drafts_saved" integer DEFAULT 0,
  "avg_response_time_minutes" numeric,
  "intent_quote_request" integer DEFAULT 0,
  "intent_tracking" integer DEFAULT 0,
  "intent_booking" integer DEFAULT 0,
  "intent_documentation" integer DEFAULT 0,
  "intent_status_inquiry" integer DEFAULT 0,
  "intent_general" integer DEFAULT 0,
  "priority_urgent" integer DEFAULT 0,
  "priority_high" integer DEFAULT 0,
  "priority_medium" integer DEFAULT 0,
  "priority_low" integer DEFAULT 0,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS public."tenant_integrations" (
  "tenant_id" uuid NOT NULL,
  "cnpj" text,
  "company_name" text,
  "trade_name" text,
  "country" text DEFAULT 'Brazil',
  "contact_name" text,
  "contact_email" text,
  "contact_phone" text,
  "serpro_client_id" text,
  "serpro_client_secret" text,
  "serpro_certificate" text,
  "serpro_cert_password" text,
  "serpro_cert_cnpj" text,
  "serpro_environment" text DEFAULT 'sandbox',
  "serpro_status" text DEFAULT 'unconfigured',
  "serpro_cert_expiry" date,
  "auto_request_missing" boolean DEFAULT false,
  "missing_data_template" text,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  "radar_status" text,
  "mapa_enabled" boolean DEFAULT false,
  "mapa_registration_number" text,
  PRIMARY KEY ("tenant_id")
);
CREATE TABLE IF NOT EXISTS public."teams" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "name" text NOT NULL,
  "manager_id" uuid,
  "invite_code" text,
  "created_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS public."quotes" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "session_id" text,
  "email_id" text,
  "email_subject" text,
  "customer_name" text,
  "customer_email" text,
  "origin" text,
  "destination" text,
  "mode" text,
  "commodity" text,
  "container_type" text,
  "weight" text,
  "incoterm" text,
  "sell_rate" numeric,
  "currency" text DEFAULT 'USD',
  "transit_time" text,
  "validity_date" date,
  "notes" text,
  "charges" jsonb,
  "status" text DEFAULT 'draft',
  "created_at" timestamp with time zone DEFAULT now(),
