  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS public."document_analysis" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "user_id" uuid,
  "document_type" text,
  "file_name" text,
  "confidence" integer,
  "raw_text" text,
  "analysis" jsonb,
  "created_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS public."shipment_events" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "shipment_id" uuid,
  "source" text,
  "event_type" text,
  "description" text,
  "location" text,
  "event_at" timestamp with time zone,
  "raw" jsonb,
  "created_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS public."rate_cards" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "session_id" text,
  "origin" text,
  "destination" text,
  "mode" text,
  "carrier" text,
  "container_type" text,
  "buy_rate" numeric,
  "sell_rate" numeric,
  "currency" text DEFAULT 'USD',
  "transit_time" text,
  "validity_start" date,
  "validity_end" date,
  "notes" text,
  "is_active" boolean DEFAULT true,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS public."organizations" (
  "id" uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
  "name" text NOT NULL,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS public."emails" (
  "id" uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
  "account_id" uuid,
  "organization_id" uuid,
  "provider_message_id" text NOT NULL,
  "thread_id" text,
  "subject" text,
  "body_text" text,
  "body_html" text,
  "from_address" text NOT NULL,
  "from_name" text,
  "to_addresses" jsonb,
  "cc_addresses" jsonb,
  "received_at" timestamp with time zone NOT NULL,
  "attachments" jsonb,
  "status" email_status DEFAULT 'pending'::email_status,
  "snoozed_until" timestamp with time zone,
  "ai_analyzed_at" timestamp with time zone,
  "ai_priority" email_priority,
  "ai_priority_reasoning" text,
  "ai_intent" email_intent,
  "ai_intent_confidence" numeric,
  "ai_summary" text,
  "extracted_data" jsonb,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS public."users" (
  "id" uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
  "organization_id" uuid,
  "email" text NOT NULL,
  "password_hash" text,
  "full_name" text,
  "role" text DEFAULT 'member',
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  PRIMARY KEY ("id"),
  UNIQUE ("email")
);
CREATE TABLE IF NOT EXISTS public."customer_portals" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "token" text NOT NULL,
  "shipment_id" uuid,
  "session_id" text,
  "title" text,
  "show_carrier" boolean DEFAULT false,
  "show_rate" boolean DEFAULT false,
  "show_documents" boolean DEFAULT false,
  "message" text,
  "is_active" boolean DEFAULT true,
  "created_at" timestamp with time zone DEFAULT now(),
  "expires_at" timestamp with time zone,
  PRIMARY KEY ("id"),
  UNIQUE ("token")
);
CREATE TABLE IF NOT EXISTS public."shipments" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "user_id" uuid,
  "status" text DEFAULT 'inquiry',
  "reference" text,
  "customer" text,
  "origin" text,
  "destination" text,
  "mode" text,
  "commodity" text,
  "weight" text,
  "container" text,
  "incoterm" text,
  "eta" text,
  "etd" text,
  "carrier" text,
  "notes" text,
  "booking_number" text,
  "bl_number" text,
  "email_id" text,
  "email_subject" text,
  "ai_generated" boolean DEFAULT false,
  "approved" boolean DEFAULT true,
  "update_target_id" uuid,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  "container_number" text,
  "t49_tracking_request_id" text,
  "t49_shipment_id" text,
  "t49_status" text,
  "t49_vessel" text,
  "t49_voyage" text,
  "t49_pol_eta" timestamp with time zone,
  "t49_pod_eta" timestamp with time zone,
  "t49_last_event" text,
  "t49_last_event_at" timestamp with time zone,
  "t49_tracking_active" boolean DEFAULT false,
  "t49_raw" jsonb,
  PRIMARY KEY ("id")
);

-- Foreign keys (added after all tables: profiles and teams reference each other)
